esqlQuery.esql:
FROM logs-vercel.logs.otel-default
| WHERE deployment.environment.name == "production"
    AND vercel.log.source == "firewall"
// vercel.proxy is a flattened field; sub-fields aren't queryable via dotted notation, use FIELD_EXTRACT instead
| EVAL waf_action = FIELD_EXTRACT(vercel.proxy, "waf_action")
// "firewall" source includes log-only entries too; isolate actual blocks
| WHERE waf_action == "deny"
| STATS denies = COUNT(*)
// Alert threshold: tune based on your application's normal WAF deny baseline.
// Consider grouping by client.address instead of a flat total if you want per-attacker alerting.
| WHERE denies > 100
